import { Alert, Badge, Button } from '../ui-kit';
import { ArrowRight } from 'lucide-react';
import { ANALYSIS_LABEL } from '../lib/overview';
import { ClassBadge, FindingRow } from './FindingParts';

const Stat = ({ label, value }) => (
  <div className="rounded-lg border border-line bg-surface-2/40 px-3 py-2"><div className="font-display text-2xl leading-none tabular-nums">{value}</div><div className="t-caption mt-1 text-fg-3">{label}</div></div>
);

/** Level 1: the default inspector view. Everything here is synthesised from stored records; nothing is generated by a model. */
export default function Overview({ model, designation, onSelectFinding, onSeeAll }) {
  const { overview: o } = model;
  const a = o.analysis;
  const imported = ['imported-synthetic', 'imported-external', 'mixed'].includes(a.detection);
  return (
    <div className="space-y-5" aria-label="Investigation overview">
      <section>
        <h3 className="t-eyebrow text-fg-3">Incident summary</h3>
        <p className="mt-1.5 text-[1.0625rem] leading-7 text-fg">{o.headline}</p>
        <div className="mt-3 grid grid-cols-5 gap-2">
          <Stat label="Sources" value={o.stats.sources} />
          <Stat label="Tracked" value={o.stats.tracked} />
          <Stat label="Key events" value={o.stats.significant} />
          <Stat label="Conflicts" value={o.stats.contradictions} />
          <Stat label="Gaps" value={o.stats.gaps} />
        </div>
        <p className="t-caption mt-2 flex flex-wrap items-center gap-x-2 text-fg-3">
          <span>Analysis:</span><span className="text-fg-2">{ANALYSIS_LABEL[a.detection]}</span>
          {a.models.length > 0 && <span className="mono">({a.models.join(', ')})</span>}
          {a.otherRuns.length > 0 && <span>· earlier run{a.otherRuns.length > 1 ? 's' : ''} not used for tracking: <span className="mono">{a.otherRuns.join(', ')}</span></span>}
          {a.failed > 0 && <Badge variant="danger">{a.failed} job failed</Badge>}
        </p>
        {imported && <Alert variant="warning" className="mt-3" title="Imported boxes, not detector output">The boxes in this case were supplied from outside the detector. Movement and events are real rule output over those boxes, but they do not show how the detector performs on this footage.</Alert>}
        {designation === 'synthetic' && !imported && <p className="t-caption mt-2 text-warning">Synthetic demonstration case.</p>}
      </section>

      <section>
        <h3 className="t-eyebrow text-fg-3">What the system found</h3>
        {o.found.length === 0
          ? <p className="t-small mt-1.5 text-fg-3">No significant findings were produced from the current data.</p>
          : <ul className="mt-2 space-y-2">{o.found.map((f) => <li key={f.id}><FindingRow f={f} onSelect={onSelectFinding} /></li>)}</ul>}
      </section>

      <section>
        <h3 className="t-eyebrow text-warning">What remains uncertain</h3>
        {o.uncertain.length === 0
          ? <p className="t-small mt-1.5 text-fg-3">No gaps or open questions were recorded.</p>
          : <ul className="mt-2 space-y-1.5">{o.uncertain.slice(0, 5).map((f) => (
              <li key={f.id}><button type="button" onClick={() => onSelectFinding(f)} className="flex w-full items-start gap-2 rounded-lg px-2 py-1.5 text-left transition hover:bg-surface-2"><i className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-warning" aria-hidden /><span className="t-small text-fg-2">{f.title}</span></button></li>
            ))}</ul>}
        {o.uncertain.length > 5 && <Button size="sm" variant="ghost" onClick={onSeeAll}>{o.uncertain.length - 5} more in Findings</Button>}
      </section>

      <section>
        <h3 className="t-eyebrow text-fg-3">Investigator attention</h3>
        {o.attention.length === 0
          ? <p className="t-small mt-1.5 text-fg-3">Nothing is flagged for immediate review.</p>
          : <ol className="mt-2 space-y-1.5">{o.attention.map((x, i) => (
              <li key={i}><button type="button" disabled={!x.findingId} onClick={() => x.findingId && onSelectFinding(model.byId[x.findingId])} className="flex w-full items-start gap-2 rounded-lg px-2 py-1.5 text-left transition hover:bg-surface-2 disabled:cursor-default">
                <ArrowRight className="mt-1 h-3.5 w-3.5 shrink-0 text-accent-text" aria-hidden /><span className="t-small text-fg">{x.text}</span></button></li>
            ))}</ol>}
        {o.unreviewed > 0 && <p className="t-caption mt-2 text-fg-3">{o.unreviewed} finding{o.unreviewed > 1 ? 's' : ''} not yet reviewed.</p>}
      </section>
      <p className="t-caption text-fg-3">Observed = measured by a machine · Reported = witness testimony · Inferred = rule-derived possibility · Unknown = missing evidence. Open any finding for its sources.</p>
    </div>
  );
}
